ins AS (INSERT INTO public.products (name,slug,category,subtitle,price,size,purity,form,storage,cas_number,short_description,description,specs,is_featured,is_bestseller,is_new,rating,review_count,created_at)
SELECT n,s,c,sub,pr,sz,pu,fo,
 CASE WHEN fo ILIKE '%powder%' THEN '-20°C, dry, protected from light' ELSE '20-25°C, protected from light' END, cas,
 n||' - '||sub||'. Supplied at '||pu||' purity ('||sz||') with a batch-specific Certificate of Analysis, for laboratory research use only.',
 n||' is a '||lower(sub)||' supplied by PeptideLabs for in-vitro and laboratory research. Every batch is manufactured under controlled conditions, independently tested by third-party laboratories and shipped with a Certificate of Analysis confirming identity, purity and content.',
 jsonb_build_array(jsonb_build_object('label','Size','value',sz),jsonb_build_object('label','Purity','value',pu),jsonb_build_object('label','Form','value',fo),jsonb_build_object('label','CAS Number','value',coalesce(nullif(cas,''),'N/A')),jsonb_build_object('label','Testing','value','HPLC, MS, third-party verified'),jsonb_build_object('label','Documentation','value','COA per batch')),
 f,b,nw, 4.6 + (i%5)*0.1, 12 + (i*7)%45, now() - make_interval(days => i)
FROM v RETURNING id, slug)
INSERT INTO public.product_images (product_id,url,position)
SELECT ins.id, '/images/products/'||v.img||'.jpg', 0 FROM ins JOIN v ON v.s = ins.slug;

WITH a AS (SELECT ARRAY['James','Emma','Liam','Olivia','Noah','Sophia','Lucas','Mia','Ethan','Ava','Oliver','Isabella','Daniel','Charlotte','Henry','Amelia','Jack','Harper','Leo','Ella','Samuel','Grace','Max','Chloe','Thomas','Lily','Adam','Zoe','Ryan','Nora','David','Hannah','Felix','Sara','Marco'] fn, ARRAY['Austin, US','London, UK','Berlin, DE','Toronto, CA','Madrid, ES','Dublin, IE','Paris, FR','Sydney, AU','Miami, US','Manchester, UK','Amsterdam, NL','Stockholm, SE','Chicago, US','Milan, IT','Zurich, CH'] lc, ARRAY['Excellent purity','Fast, discreet shipping','Great documentation','Responsive support','Consistent quality','Highly recommended','Accurate COA','Reliable supplier'] tt, ARRAY['COA matched our in-house HPLC results almost exactly. Packaging was secure and arrived cold.','Quote came back within hours and the team answered every question about storage.','We have ordered several batches now and the consistency between lots is impressive.','Shipping to Europe took four days and the parcel was plain and well protected.','Clear product pages, honest pricing and real documentation. Exactly what our lab needed.','Support helped us pick the right buffer set for our assay. Very knowledgeable team.','The reconstitution guide on the blog was genuinely useful for our new technicians.','Third-party test reports were provided without us even having to chase them.'] bd, (SELECT array_agg(name ORDER BY created_at) FROM public.products) pn)
INSERT INTO public.reviews (name,location,avatar_url,rating,title,body,product_name,created_at)
SELECT fn[g]||' '||chr(65+((g-1)*7)%26)||'.', lc[1+(g-1)%15],
 'https://randomuser.me/api/portraits/'||CASE WHEN g%2=0 THEN 'women' ELSE 'men' END||'/'||(((g-1)*3)%90+1)||'.jpg',
 CASE WHEN (g-1)%5=0 THEN 4 ELSE 5 END, tt[1+(g-1)%8], bd[1+(g-1)%8], pn[1+(g-1)%16], now() - make_interval(days => (g-1)*2)
FROM a, generate_series(1,35) g;

WITH tpl AS (SELECT E'%2$s\n\n## Introduction\nResearchers across academia and industry rely on accurate, well-documented compounds. In this article the PeptideLabs research team explains %1$s in practical terms, with reference to accepted laboratory practice.\n\n## Key Concepts\nPeptides are short chains of amino acids joined by peptide bonds. Their sequence determines folding, receptor affinity and stability. Small changes such as a single substitution, an amidated C-terminus or a fatty-acid side chain can transform half-life and potency, which is why precise identity testing matters.\n\n## Quality Considerations\nAlways verify a batch with a Certificate of Analysis. Look for HPLC purity above 98%%, a mass spectrometry trace matching the theoretical molecular weight, and a traceable lot number. Independent third-party testing adds an extra layer of confidence.\n\n## Storage and Stability\nMost lyophilised peptides are stable for months at -20°C when kept dry and dark. After reconstitution, refrigerate at 2-8°C, minimise freeze-thaw cycles and use sterile technique. Oil-based compounds should be kept at controlled room temperature.\n\n## Regulatory Notes\nRegulation varies by country. In the United States, United Kingdom and European Union many compounds are prescription-only or controlled. Research suppliers must restrict sales to qualified buyers and comply with import and export rules.\n\n## Conclusion\nUnderstanding the science, documentation and legal context helps researchers make better decisions. Contact the PeptideLabs team with any questions about specifications or documentation.'::text AS body)
INSERT INTO public.posts (title,slug,excerpt,content,cover_url,tags,published_at)
SELECT v.t,v.s,v.e,format(tpl.body,lower(v.t),v.e),v.c,v.g,v.p FROM tpl, (VALUES
('What Are Peptides and How Do They Work?','what-are-peptides','A clear introduction to peptides: structure, how they signal in biological systems, and why they matter in modern research.','/images/cat-peptides.jpg',ARRAY['peptides'],now()),
('Peptide Storage and Handling Guidelines','peptide-storage-handling','Best-practice storage temperatures, reconstitution steps and contamination control for lyophilised peptides.','/images/cat-research.jpg',ARRAY['handling'],now() - interval '6 days'),
('Understanding Certificates of Analysis (COA)','understanding-coa','How to read a COA: HPLC purity, mass spec identity, lot numbers and what to look for before using a compound.','/images/lab.jpg',ARRAY['quality'],now() - interval '12 days'),
('GLP-1 Agonists in Metabolic Research','glp1-agonists-research','An overview of GLP-1 receptor agonists such as semaglutide and tirzepatide and their role in metabolic studies.','/images/cat-biotech.jpg',ARRAY['peptides'],now() - interval '18 days'),
('Anabolic Steroids: Pharmacology and Regulation','anabolic-steroids-pharmacology','Esters, half-lives, mechanisms and the legal frameworks that govern androgen reference compounds worldwide.','/images/cat-steroids.jpg',ARRAY['steroids'],now() - interval '24 days'),
('How to Reconstitute Lyophilised Peptides','reconstitute-peptides','Step-by-step guide to reconstituting powders with bacteriostatic water, calculating concentration and avoiding degradation.','/images/cat-research.jpg',ARRAY['handling'],now() - interval '30 days')
) AS v(t,s,e,c,g,p);